    { const char * tb_v2174 = "// Это обычный C. Компилятор на Tachbit встраивает этот текст через runtime_text.tb,\n"; *(const char * *)tb_grow(v_lines) = tb_v2174; }
    { const char * tb_v2175 = "// который делает tools/embed_runtime.py. Поменял этот файл — запусти:\n"; *(const char * *)tb_grow(v_lines) = tb_v2175; }
    { const char * tb_v2176 = "//     python3 tools/embed_runtime.py\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
    { const char * tb_v2178 = "// Библиотека ядра Омниума (tb bare): то, что у обычной программы даёт ОС и libc.\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "// Загрузка (multiboot → 64 бита), своя маленькая libc, память и квоты клеток, прерывания,\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
    { const char * tb_v2180 = "// задачи и планировщик, страницы памяти, несколько ядер процессора (ACPI, APIC).\n"; *(const char * *)tb_grow(v_lines) = tb_v2180; }
    { const char * tb_v2181 = "// Компилятор вставляет этот файл в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v2181; }
    { const char * tb_v2182 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2182; }
    { const char * tb_v2183 = "// ---------- режим без ОС (tb bare): своя маленькая библиотека вместо libc ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2183; }
    { const char * tb_v2184 = "// Программа сама себе ОС: загружается через multiboot (QEMU, GRUB), пишет на экран\n"; *(const char * *)tb_grow(v_lines) = tb_v2184; }
    { const char * tb_v2185 = "// (текстовый режим VGA) и в последовательный порт COM1, память берёт из своего запаса.\n"; *(const char * *)tb_grow(v_lines) = tb_v2185; }
    { const char * tb_v2186 = "// Есть прерывания, таймер, клавиатура, задачи (background) и страницы памяти; файлов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v2186; }
    { const char * tb_v2187 = "#include <stddef.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2187; }
    { const char * tb_v2188 = "#include <stdarg.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2188; }
    { const char * tb_v2189 = "#include <stdint.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2189; }
    { const char * tb_v2190 = "// «переменные потока» — настоящие: у каждой задачи свой блок, на него смотрит регистр FS\n"; *(const char * *)tb_grow(v_lines) = tb_v2190; }
    { const char * tb_v2191 = "// (так их не надо копировать при смене задачи, и на нескольких ядрах процессора у каждого свои)\n"; *(const char * *)tb_grow(v_lines) = tb_v2191; }
    { const char * tb_v2192 = "#define _Thread_local __thread __attribute__((tls_model(\"local-exec\")))\n"; *(const char * *)tb_grow(v_lines) = tb_v2192; }
    { const char * tb_v2193 = "#define EOF (-1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2193; }
    { const char * tb_v2194 = "typedef struct tb_file FILE;\n"; *(const char * *)tb_grow(v_lines) = tb_v2194; }
    { const char * tb_v2195 = "#define stdout ((FILE *)1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2195; }
    { const char * tb_v2196 = "#define stderr ((FILE *)2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2196; }
    { const char * tb_v2197 = "typedef long pthread_t;   // 8 байт, как адрес: раскладка задачи та же, что в обычной программе\n"; *(const char * *)tb_grow(v_lines) = tb_v2197; }
    { const char * tb_v2198 = "typedef int pthread_mutex_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v2198; }
    { const char * tb_v2199 = "#define PTHREAD_MUTEX_INITIALIZER 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2199; }
    { const char * tb_v2200 = "#define pthread_mutex_lock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v2200; }
    { const char * tb_v2201 = "#define pthread_mutex_unlock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v2201; }
    { const char * tb_v2202 = "#define _SC_NPROCESSORS_ONLN 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2202; }
    { const char * tb_v2203 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2203; }
    { const char * tb_v2204 = "TB_INL void tb_outb(unsigned short port, unsigned char v) { __asm__ volatile(\"outb %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2204; }
    { const char * tb_v2205 = "TB_INL unsigned char tb_inb(unsigned short port) { unsigned char v; __asm__ volatile(\"inb %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2205; }
    { const char * tb_v2206 = "TB_INL void tb_outw(unsigned short port, unsigned short v) { __asm__ volatile(\"outw %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "TB_INL unsigned short tb_inw(unsigned short port) { unsigned short v; __asm__ volatile(\"inw %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
    { const char * tb_v2208 = "TB_INL void tb_outl(unsigned short port, unsigned int v) { __asm__ volatile(\"outl %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2208; }
    { const char * tb_v2209 = "TB_INL unsigned int tb_inl(unsigned short port) { unsigned int v; __asm__ volatile(\"inl %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2209; }
    { const char * tb_v2210 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v2210; }
    { const char * tb_v2211 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
    { const char * tb_v2213 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
    { const char * tb_v2214 = "    struct tb_cpu_s *self;\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "    int id, apic, run, slice, depth, prev;   // run: номер задачи (-1 — пустой ход); depth: вложенность «общего замка»; prev: задача, которую отпустить после смены стека\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
    { const char * tb_v2216 = "    uint64_t *idle_frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "    unsigned char irq_tls[512 + 16] __attribute__((aligned(16)));   // переменные потока для функций прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
    { const char * tb_v2218 = "    unsigned char idle_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2218; }
    { const char * tb_v2219 = "    unsigned char df_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2219; }
    { const char * tb_v2220 = "} tb_cpu;\n"; *(const char * *)tb_grow(v_lines) = tb_v2220; }
    { const char * tb_v2221 = "TB_API tb_cpu tb_cpus[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v2221; }
    { const char * tb_v2222 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2222; }
    { const char * tb_v2223 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2223; }
    { const char * tb_v2224 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v2224; }
    { const char * tb_v2225 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v2225; }
    { const char * tb_v2226 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2226; }
    { const char * tb_v2227 = "TB_INL uint64_t tb_irq_save(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2227; }
    { const char * tb_v2228 = "    uint64_t f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2228; }
    { const char * tb_v2229 = "    __asm__ volatile(\"pushfq\\npopq %0\\ncli\" : \"=r\"(f) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2229; }
    { const char * tb_v2230 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "    if (c->depth++ == 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "        while (__atomic_exchange_n(&tb_bkl, 1, __ATOMIC_ACQUIRE)) __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
    { const char * tb_v2234 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "TB_INL void tb_irq_restore(uint64_t f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
    { const char * tb_v2237 = "    if (--c->depth == 0) __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2237; }
    { const char * tb_v2238 = "    __asm__ volatile(\"pushq %0\\npopfq\" : : \"r\"(f) : \"memory\", \"cc\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2238; }
    { const char * tb_v2239 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2239; }
    { const char * tb_v2240 = "// отдать общий замок целиком (задача уходит навсегда — падает или кончилась)\n"; *(const char * *)tb_grow(v_lines) = tb_v2240; }
    { const char * tb_v2241 = "TB_INL void tb_bkl_drop(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2241; }
    { const char * tb_v2242 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "    if (c->depth > 0) { c->depth = 0; __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
    { const char * tb_v2244 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
    { const char * tb_v2246 = "// экран 80×25: байт буквы и байт цвета; русские буквы рисуем своим шрифтом (см. tb_vga_font)\n"; *(const char * *)tb_grow(v_lines) = tb_v2246; }
