    { const char * tb_v2255 = "        if (++tb_vcol == 80) { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
    { const char * tb_v2256 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2256; }
    { const char * tb_v2257 = "    if (tb_vrow == 25) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2257; }
    { const char * tb_v2258 = "        for (int i = 0; i < 24 * 80; i++) tb_vga[i] = tb_vga[i + 80];\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "        for (int i = 24 * 80; i < 25 * 80; i++) tb_vga[i] = (unsigned short)(tb_vcolor << 8 | ' ');\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
