    { const char * tb_v2384 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2384; }
    { const char * tb_v2385 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v2385; }
    { const char * tb_v2386 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
