    { const char * tb_v2397 = "// заголовок куска: размер (номер 4..31) + метка «это начало куска» — так по адресу видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "// наш ли это кусок (для передачи владения), и хозяин (клетка) рядом\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "#define TB_HMAGIC 0x0B1A0C0000000000ull\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
