    { const char * tb_v2687 = "TB_API double log(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2687; }
    { const char * tb_v2688 = "    if (x <= 0) return -1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v2688; }
