    { const char * tb_v2958 = "// --- клавиатура: буквы копятся в очереди, read_key() берёт по одной ---\n"; *(const char * *)tb_grow(v_lines) = tb_v2958; }
    { const char * tb_v2959 = "TB_API const char tb_kmap[2][58] = {\n"; *(const char * *)tb_grow(v_lines) = tb_v2959; }
    { const char * tb_v2960 = "    {0, 27, '1', '2', '3', '4', '5', '6', '7', '8', '9', '0', '-', '=', '\\b', '\\t',\n"; *(const char * *)tb_grow(v_lines) = tb_v2960; }
    { const char * tb_v2961 = "     'q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '[', ']', '\\n', 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "     'a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l', ';', '\\'', '`', 0, '\\\\',\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "     'z', 'x', 'c', 'v', 'b', 'n', 'm', ',', '.', '/', 0, '*', 0, ' '},\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
    { const char * tb_v2964 = "    {0, 27, '!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '_', '+', '\\b', '\\t',\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
    { const char * tb_v2965 = "     'Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P', '{', '}', '\\n', 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v2965; }
    { const char * tb_v2966 = "     'A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L', ':', '\"', '~', 0, '|',\n"; *(const char * *)tb_grow(v_lines) = tb_v2966; }
    { const char * tb_v2967 = "     'Z', 'X', 'C', 'V', 'B', 'N', 'M', '<', '>', '?', 0, '*', 0, ' '}};\n"; *(const char * *)tb_grow(v_lines) = tb_v2967; }
    { const char * tb_v2968 = "TB_API char tb_kq[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2968; }
    { const char * tb_v2969 = "TB_API volatile unsigned char tb_khead = 0, tb_ktail = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2969; }
    { const char * tb_v2970 = "TB_API int tb_kshift = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2970; }
    { const char * tb_v2971 = "TB_API char tb_ktext[256][2];\n"; *(const char * *)tb_grow(v_lines) = tb_v2971; }
    { const char * tb_v2972 = "// окно открыто (window_open): клавиши идут и сюда — для key_down и typed_text\n"; *(const char * *)tb_grow(v_lines) = tb_v2972; }
    { const char * tb_v2973 = "TB_API void (*tb_key_hook)(unsigned char sc) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2973; }
    { const char * tb_v2974 = "TB_API void tb_key_byte(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2974; }
    { const char * tb_v2975 = "    if (tb_key_hook) tb_key_hook(sc);\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "    if (sc == 0x2A || sc == 0x36) { tb_kshift = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
    { const char * tb_v2977 = "    if (sc == 0xAA || sc == 0xB6) { tb_kshift = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2977; }
    { const char * tb_v2978 = "    if (sc >= 58) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2978; }
    { const char * tb_v2979 = "    char ch = tb_kmap[tb_kshift][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v2979; }
    { const char * tb_v2980 = "    if (ch == 0 || (unsigned char)(tb_khead + 1) == tb_ktail) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2980; }
    { const char * tb_v2981 = "    tb_kq[tb_khead] = ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v2981; }
    { const char * tb_v2982 = "    tb_khead = (unsigned char)(tb_khead + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2982; }
    { const char * tb_v2983 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2983; }
    { const char * tb_v2984 = "TB_API void tb_key_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2984; }
    { const char * tb_v2985 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v2985; }
    { const char * tb_v2986 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2986; }
    { const char * tb_v2987 = "    unsigned char b = tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
    { const char * tb_v2988 = "    if (st & 0x20) return;   // байт мыши (его ждёт прерывание 12)\n"; *(const char * *)tb_grow(v_lines) = tb_v2988; }
    { const char * tb_v2989 = "    tb_key_byte(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v2989; }
    { const char * tb_v2990 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2990; }
    { const char * tb_v2991 = "TB_API const char *tb_read_key(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2991; }
    { const char * tb_v2992 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v2992; }
    { const char * tb_v2993 = "    const char *r = \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2993; }
    { const char * tb_v2994 = "    if (tb_ktail != tb_khead) { r = tb_ktext[(unsigned char)tb_kq[tb_ktail]]; tb_ktail = (unsigned char)(tb_ktail + 1); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2994; }
    { const char * tb_v2995 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v2995; }
    { const char * tb_v2996 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2996; }
    { const char * tb_v2997 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2997; }
    { const char * tb_v2998 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2998; }
    { const char * tb_v2999 = "// --- страницы памяти (4 уровня): нижняя память — страницы по 4 КБ (адрес 0 и код защищены,\n"; *(const char * *)tb_grow(v_lines) = tb_v2999; }
    { const char * tb_v3000 = "// у стеков — пустая страница-сторож), выше — большие по 2 МБ (куча и свободная память) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3000; }
    { const char * tb_v3001 = "#define TB_LOW_PTS 32                                 // 32 таблицы × 2 МБ = нижние 64 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v3001; }
    { const char * tb_v3002 = "#define TB_MAX_GB 64                                  // память до 64 ГБ\n"; *(const char * *)tb_grow(v_lines) = tb_v3002; }
    { const char * tb_v3003 = "TB_API uint64_t tb_pml4[512] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3003; }
    { const char * tb_v3004 = "TB_API uint64_t tb_pdpt[512] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3004; }
    { const char * tb_v3005 = "TB_API uint64_t tb_pdir[TB_MAX_GB][512] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3005; }
    { const char * tb_v3006 = "TB_API uint64_t tb_pt[TB_LOW_PTS][512] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3006; }
    { const char * tb_v3007 = "TB_API uint64_t tb_ram_end = 0, tb_pg_next = 0, tb_pg_free = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3007; }
    { const char * tb_v3008 = "// таблицы на время загрузки: первые 4 ГБ большими страницами (их строит _start ещё в 32 битах)\n"; *(const char * *)tb_grow(v_lines) = tb_v3008; }
    { const char * tb_v3009 = "TB_API uint64_t tb_boot_pml4[512] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3009; }
    { const char * tb_v3010 = "TB_API uint64_t tb_boot_pdpt[512] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3010; }
    { const char * tb_v3011 = "TB_API uint64_t tb_boot_pd[4][512] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3011; }
    { const char * tb_v3012 = "TB_API uint32_t tb_boot_magic __attribute__((used)), tb_boot_mbi __attribute__((used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3012; }
    { const char * tb_v3013 = "// ---- модули (файлы, которые загрузчик положил рядом с ядром: qemu -initrd \"a.oapp,b.oapp\") ----\n"; *(const char * *)tb_grow(v_lines) = tb_v3013; }
    { const char * tb_v3014 = "// у Multiboot: флаг 3 — есть модули; mbi[5] — сколько, mbi[6] — где список (по 16 байт: начало, конец, имя, 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3014; }
    { const char * tb_v3015 = "TB_API uint32_t *tb_mods(long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3015; }
    { const char * tb_v3016 = "    uint32_t *mbi = (uint32_t *)(uintptr_t)tb_boot_mbi;\n"; *(const char * *)tb_grow(v_lines) = tb_v3016; }
    { const char * tb_v3017 = "    *n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "    if (tb_boot_magic != 0x2BADB002u || mbi == 0 || !(mbi[0] & 8)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
    { const char * tb_v3019 = "    *n = mbi[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "    return (uint32_t *)(uintptr_t)mbi[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
    { const char * tb_v3021 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3021; }
    { const char * tb_v3022 = "TB_API uint64_t tb_mods_top(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3022; }
    { const char * tb_v3023 = "    long long n; uint32_t *m = tb_mods(&n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3023; }
    { const char * tb_v3024 = "    uint64_t top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3024; }
    { const char * tb_v3025 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3025; }
    { const char * tb_v3026 = "        if (m[4 * i + 1] > top) top = m[4 * i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3026; }
    { const char * tb_v3027 = "        const char *nm = (const char *)(uintptr_t)m[4 * i + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v3027; }
    { const char * tb_v3028 = "        if (nm) { uint64_t e = (uint64_t)(uintptr_t)nm + strlen(nm) + 1; if (e > top) top = e; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3028; }
    { const char * tb_v3029 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3029; }
    { const char * tb_v3030 = "    if (n > 0 && (uint64_t)(uintptr_t)(m + 4 * n) > top) top = (uint64_t)(uintptr_t)(m + 4 * n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3030; }
    { const char * tb_v3031 = "    return top;\n"; *(const char * *)tb_grow(v_lines) = tb_v3031; }
    { const char * tb_v3032 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "TB_API long long tb_module_count(void) { long long n; tb_mods(&n); return n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "TB_API long long tb_module_addr(long long i) { long long n; uint32_t *m = tb_mods(&n); return i >= 0 && i < n ? m[4 * i] : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
    { const char * tb_v3035 = "TB_API long long tb_module_size(long long i) { long long n; uint32_t *m = tb_mods(&n); return i >= 0 && i < n ? (long long)m[4 * i + 1] - m[4 * i] : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "// таблица имён ядра (её заполняет компоновщик elf_link.py): по алфавиту, 16 байт на имя —\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "// адрес, где имя (от начала таблицы), длина имени. Программы Омниума находят по ней функции ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
    { const char * tb_v3038 = "TB_API volatile uint64_t tb_ksym_tab __attribute__((used)) = 1, tb_ksym_n __attribute__((used)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3038; }
    { const char * tb_v3039 = "TB_API long long tb_kernel_symbol(const char *nm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3039; }
    { const char * tb_v3040 = "    uint64_t t = tb_ksym_tab;\n"; *(const char * *)tb_grow(v_lines) = tb_v3040; }
    { const char * tb_v3041 = "    long long lo = 0, hi = (long long)tb_ksym_n - 1, len = (long long)strlen(nm);\n"; *(const char * *)tb_grow(v_lines) = tb_v3041; }
    { const char * tb_v3042 = "    if (t <= 1) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3042; }
    { const char * tb_v3043 = "    while (lo <= hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3043; }
    { const char * tb_v3044 = "        long long mid = (lo + hi) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3044; }
    { const char * tb_v3045 = "        const uint64_t *e = (const uint64_t *)(uintptr_t)(t + 16 * mid);\n"; *(const char * *)tb_grow(v_lines) = tb_v3045; }
    { const char * tb_v3046 = "        uint32_t off = (uint32_t)e[1], n = (uint32_t)(e[1] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
    { const char * tb_v3047 = "        int r = memcmp((const char *)(uintptr_t)(t + off), nm, (size_t)(n < len ? n : len));\n"; *(const char * *)tb_grow(v_lines) = tb_v3047; }
    { const char * tb_v3048 = "        if (r == 0) r = n < len ? -1 : n > len ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
    { const char * tb_v3049 = "        if (r == 0) return (long long)e[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
    { const char * tb_v3050 = "        if (r < 0) lo = mid + 1; else hi = mid - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3050; }
    { const char * tb_v3051 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3051; }
    { const char * tb_v3052 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3052; }
    { const char * tb_v3053 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3053; }
    { const char * tb_v3054 = "// позвать функцию по адресу (начало загруженной программы): без параметров, без ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3054; }
    { const char * tb_v3055 = "TB_API void tb_call_address(long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3055; }
    { const char * tb_v3056 = "    if (a == 0) tb_panic(\"call_address: адрес 0\", 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3056; }
    { const char * tb_v3057 = "    ((void (*)(void))(uintptr_t)a)();\n"; *(const char * *)tb_grow(v_lines) = tb_v3057; }
    { const char * tb_v3058 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3058; }
    { const char * tb_v3059 = "TB_API void tb_unmap(uint64_t a) { tb_pt[a >> 21][(a >> 12) & 511] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3059; }
    { const char * tb_v3060 = "TB_API int tb_is_guard(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3060; }
    { const char * tb_v3061 = "    if (a >= (uint64_t)(uintptr_t)tb_stack && a < (uint64_t)(uintptr_t)tb_stack + 4096) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3061; }
    { const char * tb_v3062 = "    for (int i = 1; i < TB_NTASK; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3062; }
    { const char * tb_v3063 = "        if (a >= (uint64_t)(uintptr_t)tb_tstacks[i] && a < (uint64_t)(uintptr_t)tb_tstacks[i] + 4096) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
    { const char * tb_v3064 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3064; }
    { const char * tb_v3065 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
    { const char * tb_v3066 = "TB_API void tb_paging_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3066; }
    { const char * tb_v3067 = "    uint64_t low = (uint64_t)(uintptr_t)tb_heap_area;\n"; *(const char * *)tb_grow(v_lines) = tb_v3067; }
    { const char * tb_v3068 = "    uint64_t cs = (uint64_t)(uintptr_t)tb_code_start, ce = (uint64_t)(uintptr_t)tb_code_end;\n"; *(const char * *)tb_grow(v_lines) = tb_v3068; }
    { const char * tb_v3069 = "    if (low > TB_LOW_PTS * 0x200000ull) tb_panic(\"ядро слишком большое для нижних страниц\", low, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3069; }
    { const char * tb_v3070 = "    if (tb_ram_end < (uint64_t)(uintptr_t)tb_kernel_end + 0x400000u) tb_panic(\"мало памяти: запусти qemu с -m 256\", tb_ram_end, (uint64_t)(uintptr_t)tb_kernel_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3070; }
    { const char * tb_v3071 = "    for (uint64_t a = 0; a < low; a += 4096) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3071; }
    { const char * tb_v3072 = "        uint64_t flags = 3;                                   // есть, можно писать\n"; *(const char * *)tb_grow(v_lines) = tb_v3072; }
    { const char * tb_v3073 = "        if (a >= cs && a < ce) flags = 1;                     // код: только читать\n"; *(const char * *)tb_grow(v_lines) = tb_v3073; }
    { const char * tb_v3074 = "        tb_pt[a >> 21][(a >> 12) & 511] = a | flags;\n"; *(const char * *)tb_grow(v_lines) = tb_v3074; }
    { const char * tb_v3075 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3075; }
    { const char * tb_v3076 = "    tb_unmap(0);                                              // адрес 0: «пустая ссылка»\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "    tb_unmap((uint64_t)(uintptr_t)tb_stack);                  // сторож под стеком main\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "    for (int i = 1; i < TB_NTASK; i++) tb_unmap((uint64_t)(uintptr_t)tb_tstacks[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "    tb_pml4[0] = (uint64_t)(uintptr_t)tb_pdpt | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
    { const char * tb_v3080 = "    uint64_t gbs = (tb_ram_end + (1ull << 30) - 1) >> 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v3080; }
    { const char * tb_v3081 = "    if (gbs > TB_MAX_GB) gbs = TB_MAX_GB;\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "    if (gbs < 1) gbs = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "    for (uint64_t g = 0; g < gbs; g++) tb_pdpt[g] = (uint64_t)(uintptr_t)tb_pdir[g] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "    for (uint64_t t = 0; t < low >> 21; t++) tb_pdir[0][t] = (uint64_t)(uintptr_t)tb_pt[t] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "    for (uint64_t a = low; a < tb_ram_end; a += 0x200000ull) tb_pdir[a >> 30][(a >> 21) & 511] = a | 0x83;\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "    // окна устройств PCI (AHCI, NVMe, APIC ...) — от 3 до 4 ГБ, без кэша; память там не трогаем\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
