    { const char * tb_v3777 = "    \"mesh_image(сетка, картинка) — картинка из load_image; -1 — без картинки\", \"mesh_image(mesh, picture) — a picture from load_image; -1 — no picture\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
