    { const char * tb_v4596 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4596; }
    { const char * tb_v4597 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4597; }
    { const char * tb_v4598 = "    if (tb_cell_can_fall()) tb_cell_fall(msg, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4598; }
