    { const char * tb_v4610 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4610; }
    { const char * tb_v4611 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4611; }
    { const char * tb_v4612 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4612; }
    { const char * tb_v4613 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4613; }
    { const char * tb_v4614 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4614; }
    { const char * tb_v4615 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4615; }
    { const char * tb_v4616 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4616; }
    { const char * tb_v4617 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4617; }
    { const char * tb_v4618 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4618; }
    { const char * tb_v4619 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4619; }
    { const char * tb_v4620 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4620; }
    { const char * tb_v4621 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4621; }
    { const char * tb_v4622 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4622; }
    { const char * tb_v4623 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4623; }
    { const char * tb_v4624 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4624; }
    { const char * tb_v4625 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4625; }
    { const char * tb_v4626 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4626; }
    { const char * tb_v4627 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4627; }
    { const char * tb_v4628 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4628; }
    { const char * tb_v4629 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4629; }
    { const char * tb_v4630 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4630; }
    { const char * tb_v4631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4631; }
    { const char * tb_v4632 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4632; }
    { const char * tb_v4633 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4633; }
    { const char * tb_v4634 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4634; }
    { const char * tb_v4635 = "TB_API _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4635; }
    { const char * tb_v4636 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v4636; }
    { const char * tb_v4637 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4637; }
    { const char * tb_v4638 = "TB_API void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4638; }
    { const char * tb_v4639 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4639; }
    { const char * tb_v4640 = "    char *a = (char *)si->si_addr;\n"; *(const char * *)tb_grow(v_lines) = tb_v4640; }
    { const char * tb_v4641 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4641; }
    { const char * tb_v4642 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4642; }
    { const char * tb_v4643 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v4643; }
    { const char * tb_v4644 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v4644; }
    { const char * tb_v4645 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4645; }
    { const char * tb_v4646 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4646; }
    { const char * tb_v4647 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4647; }
    { const char * tb_v4648 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v4648; }
    { const char * tb_v4649 = "        m = tb_lang_en_v == 1 ? \"the stack is full: a function calls itself too deep (endless recursion?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4649; }
    { const char * tb_v4650 = "                              : \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4650; }
    { const char * tb_v4651 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v4651; }
    { const char * tb_v4652 = "        m = tb_lang_en_v == 1 ? \"the program crashed: memory error. This is a Tachbit bug, not yours: please send this program\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4652; }
    { const char * tb_v4653 = "                              : \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4653; }
    { const char * tb_v4654 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4654; }
    { const char * tb_v4655 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4655; }
    { const char * tb_v4656 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4656; }
    { const char * tb_v4657 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4657; }
    { const char * tb_v4658 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v4658; }
    { const char * tb_v4659 = "TB_API void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4659; }
    { const char * tb_v4660 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v4660; }
    { const char * tb_v4661 = "    ss.ss_sp = malloc(65536); ss.ss_size = 65536; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4661; }
    { const char * tb_v4662 = "    if (ss.ss_sp) sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4662; }
    { const char * tb_v4663 = "    tb_main_sp = here;\n"; *(const char * *)tb_grow(v_lines) = tb_v4663; }
    { const char * tb_v4664 = "    tb_stack_lim = lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4664; }
    { const char * tb_v4665 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4665; }
    { const char * tb_v4666 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v4666; }
    { const char * tb_v4667 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v4667; }
    { const char * tb_v4668 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4668; }
    { const char * tb_v4669 = "// короткое ожидание без сна (подсказка процессору)\n"; *(const char * *)tb_grow(v_lines) = tb_v4669; }
    { const char * tb_v4670 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v4670; }
