    { const char * tb_v4927 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4927; }
    { const char * tb_v4928 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4928; }
    { const char * tb_v4929 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4929; }
    { const char * tb_v4930 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4930; }
