    { const char * tb_v5538 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5538; }
    { const char * tb_v5539 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5539; }
    { const char * tb_v5540 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5540; }
    { const char * tb_v5541 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5541; }
