    { const char * tb_v5545 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5545; }
    { const char * tb_v5546 = "    return n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5546; }
    { const char * tb_v5547 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "// память о последних текстах: адрес, байты, буквы и где мы стояли (буква li начинается с байта bi).\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
    { const char * tb_v5549 = "// s[i] подряд в цикле — шаг вперёд от прошлого места, а не счёт с начала.\n"; *(const char * *)tb_grow(v_lines) = tb_v5549; }
    { const char * tb_v5550 = "typedef struct { const char *p; long long nb, nl, li, bi; } tb_u8slot;\n"; *(const char * *)tb_grow(v_lines) = tb_v5550; }
    { const char * tb_v5551 = "TB_API _Thread_local tb_u8slot tb_u8c[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v5551; }
