    { const char * tb_v6277 = "    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v6277; }
    { const char * tb_v6278 = "    return (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;\n"; *(const char * *)tb_grow(v_lines) = tb_v6278; }
    { const char * tb_v6279 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6279; }
    { const char * tb_v6280 = "TB_API void tb_wait_ms(long long n) { fflush(stdout); if (n > 0) usleep((useconds_t)(n * 1000)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6280; }
    { const char * tb_v6281 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6281; }
    { const char * tb_v6282 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6282; }
    { const char * tb_v6283 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v6283; }
    { const char * tb_v6284 = "TB_API long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6284; }
    { const char * tb_v6285 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6285; }
    { const char * tb_v6286 = "    return (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6286; }
    { const char * tb_v6287 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6287; }
    { const char * tb_v6288 = "// цвет с непрозрачностью a: 255 — сплошной (как rgb), 0 — не виден. Рисование смешивает его с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v6288; }
    { const char * tb_v6289 = "TB_API long long tb_rgba(long long r, long long g, long long b, long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6289; }
    { const char * tb_v6290 = "    a = a < 0 ? 0 : a > 255 ? 255 : a;\n"; *(const char * *)tb_grow(v_lines) = tb_v6290; }
    { const char * tb_v6291 = "    return ((255 - a) << 24) | tb_rgb(r, g, b);\n"; *(const char * *)tb_grow(v_lines) = tb_v6291; }
    { const char * tb_v6292 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6292; }
    { const char * tb_v6293 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v6293; }
    { const char * tb_v6294 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6294; }
    { const char * tb_v6295 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6295; }
    { const char * tb_v6296 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6296; }
    { const char * tb_v6297 = "        unsigned lo, hi; __asm__ volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n"; *(const char * *)tb_grow(v_lines) = tb_v6297; }
    { const char * tb_v6298 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6298; }
    { const char * tb_v6299 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6299; }
    { const char * tb_v6300 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v6300; }
    { const char * tb_v6301 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6301; }
    { const char * tb_v6302 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6302; }
    { const char * tb_v6303 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6303; }
    { const char * tb_v6304 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6304; }
    { const char * tb_v6305 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v6305; }
    { const char * tb_v6306 = "    unsigned long long span = (unsigned long long)(b - a) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6306; }
    { const char * tb_v6307 = "    return span == 0 ? (long long)tb_rand_state : a + (long long)(tb_rand_state % span);\n"; *(const char * *)tb_grow(v_lines) = tb_v6307; }
    { const char * tb_v6308 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6308; }
    { const char * tb_v6309 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6309; }
