    { const char * tb_v6339 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6339; }
    { const char * tb_v6340 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6340; }
    { const char * tb_v6341 = "        tb_list *r = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v6341; }
