    { const char * tb_v6343 = "        r->len = l->len; r->cap = l->cap; r->size = 0; r->data = tb_mem_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6343; }
    { const char * tb_v6344 = "        memcpy(r->data, l->data, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6344; }
    { const char * tb_v6345 = "        return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6345; }
