    { const char * tb_v6348 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6348; }
    { const char * tb_v6349 = "TB_API void tb_sort_list(tb_list *l, int (*cmp)(const void *, const void *)) { qsort(l->data, l->len, l->size, cmp); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6349; }
    { const char * tb_v6350 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6350; }
    { const char * tb_v6351 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v6351; }
    { const char * tb_v6352 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v6352; }
    { const char * tb_v6353 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v6353; }
    { const char * tb_v6354 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v6354; }
    { const char * tb_v6355 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6355; }
    { const char * tb_v6356 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v6356; }
    { const char * tb_v6357 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v6357; }
    { const char * tb_v6358 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v6358; }
    { const char * tb_v6359 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v6359; }
    { const char * tb_v6360 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6360; }
    { const char * tb_v6361 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v6361; }
    { const char * tb_v6362 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6362; }
    { const char * tb_v6363 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6363; }
    { const char * tb_v6364 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6364; }
    { const char * tb_v6365 = "    tb_export(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v6365; }
    { const char * tb_v6366 = "    tb_export(l);\n"; *(const char * *)tb_grow(v_lines) = tb_v6366; }
    { const char * tb_v6367 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6367; }
    { const char * tb_v6368 = "TB_API void tb_export_dict(tb_dict *d, int ktext, int vtext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6368; }
    { const char * tb_v6369 = "    if (!d) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6369; }
    { const char * tb_v6370 = "    tb_export_list(d->keys, ktext);\n"; *(const char * *)tb_grow(v_lines) = tb_v6370; }
    { const char * tb_v6371 = "    tb_export_list(d->vals, vtext);\n"; *(const char * *)tb_grow(v_lines) = tb_v6371; }
    { const char * tb_v6372 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6372; }
    { const char * tb_v6373 = "    tb_export(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v6373; }
    { const char * tb_v6374 = "    tb_export(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6374; }
    { const char * tb_v6375 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
    { const char * tb_v6376 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6376; }
    { const char * tb_v6377 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6377; }
    { const char * tb_v6378 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v6378; }
    { const char * tb_v6379 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v6379; }
    { const char * tb_v6380 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v6380; }
    { const char * tb_v6381 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6381; }
    { const char * tb_v6382 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6382; }
    { const char * tb_v6383 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6383; }
    { const char * tb_v6384 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6384; }
    { const char * tb_v6385 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6385; }
    { const char * tb_v6386 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6386; }
    { const char * tb_v6387 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6387; }
    { const char * tb_v6388 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6388; }
    { const char * tb_v6389 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6389; }
    { const char * tb_v6390 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6390; }
    { const char * tb_v6391 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6391; }
    { const char * tb_v6392 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6392; }
    { const char * tb_v6393 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6393; }
    { const char * tb_v6394 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6394; }
    { const char * tb_v6395 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6395; }
    { const char * tb_v6396 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6396; }
    { const char * tb_v6397 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6397; }
    { const char * tb_v6398 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v6398; }
    { const char * tb_v6399 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6399; }
    { const char * tb_v6400 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6400; }
    { const char * tb_v6401 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6401; }
    { const char * tb_v6402 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v6402; }
    { const char * tb_v6403 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6403; }
    { const char * tb_v6404 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6404; }
    { const char * tb_v6405 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6405; }
    { const char * tb_v6406 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v6406; }
    { const char * tb_v6407 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6407; }
    { const char * tb_v6408 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6408; }
    { const char * tb_v6409 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v6409; }
    { const char * tb_v6410 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6410; }
    { const char * tb_v6411 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6411; }
    { const char * tb_v6412 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v6412; }
    { const char * tb_v6413 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6413; }
    { const char * tb_v6414 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6414; }
