    { const char * tb_v6586 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v6586; }
    { const char * tb_v6587 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6587; }
    { const char * tb_v6588 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6588; }
