    { const char * tb_v6595 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
    { const char * tb_v6596 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6596; }
    { const char * tb_v6597 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v6597; }
    { const char * tb_v6598 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6598; }
