    { const char * tb_v6769 = "typedef struct { uintptr_t a; uint64_t n; int live, line, fline; } tb_memb;\n"; *(const char * *)tb_grow(v_lines) = tb_v6769; }
    { const char * tb_v6770 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6770; }
