    { const char * tb_v6775 = "TB_INL int tb_memchk(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6775; }
    { const char * tb_v6776 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6776; }
    { const char * tb_v6777 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6777; }
