    { const char * tb_v6784 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6784; }
    { const char * tb_v6785 = "    return tb_mem_check;\n"; *(const char * *)tb_grow(v_lines) = tb_v6785; }
    { const char * tb_v6786 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6786; }
    { const char * tb_v6787 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v6787; }
