    { const char * tb_v6835 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
    { const char * tb_v6837 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6837; }
    { const char * tb_v6838 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6838; }
