    { const char * tb_v7143 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v7143; }
    { const char * tb_v7144 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
    { const char * tb_v7145 = "// Клетка помнит, какие замки держит: упадёт — ядро их отпустит\n"; *(const char * *)tb_grow(v_lines) = tb_v7145; }
    { const char * tb_v7146 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7146; }
