    { const char * tb_v7148 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) { tb_irq_restore(f); tb_yield(); f = tb_irq_save(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7148; }
    { const char * tb_v7149 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
    { const char * tb_v7150 = "    if (!tb_in_irq && s->nlocks < 8) s->locks[s->nlocks++] = l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7150; }
    { const char * tb_v7151 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7151; }
