    { const char * tb_v7154 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v7154; }
    { const char * tb_v7155 = "    if (!tb_in_irq)\n"; *(const char * *)tb_grow(v_lines) = tb_v7155; }
    { const char * tb_v7156 = "        for (int i = s->nlocks - 1; i >= 0; i--)\n"; *(const char * *)tb_grow(v_lines) = tb_v7156; }
    { const char * tb_v7157 = "            if (s->locks[i] == l) { s->locks[i] = s->locks[--s->nlocks]; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7157; }
    { const char * tb_v7158 = "    __atomic_store_n(l, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v7158; }
    { const char * tb_v7159 = "    tb_irq_restore((uint64_t)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v7159; }
    { const char * tb_v7160 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7160; }
    { const char * tb_v7161 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v7161; }
    { const char * tb_v7162 = "// замок в программе: атомарный обмен; занято — сначала коротко ждём, потом уступаем ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v7162; }
    { const char * tb_v7163 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7163; }
    { const char * tb_v7164 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "        for (int i = 0; __atomic_load_n(l, __ATOMIC_RELAXED); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "            if (i >= 64) sched_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "            else __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
