    { const char * tb_v7509 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7509; }
    { const char * tb_v7510 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v7510; }
    { const char * tb_v7511 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v7511; }
    { const char * tb_v7512 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v7512; }
    { const char * tb_v7513 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v7513; }
    { const char * tb_v7514 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7514; }
    { const char * tb_v7515 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7515; }
    { const char * tb_v7516 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7516; }
    { const char * tb_v7517 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7517; }
    { const char * tb_v7518 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7518; }
    { const char * tb_v7519 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7519; }
    { const char * tb_v7520 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7520; }
    { const char * tb_v7521 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7521; }
    { const char * tb_v7522 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7522; }
    { const char * tb_v7523 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7523; }
    { const char * tb_v7524 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7524; }
    { const char * tb_v7525 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v7525; }
    { const char * tb_v7526 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7526; }
    { const char * tb_v7527 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7527; }
    { const char * tb_v7528 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7528; }
    { const char * tb_v7529 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7529; }
    { const char * tb_v7530 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7530; }
    { const char * tb_v7531 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7531; }
    { const char * tb_v7532 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7532; }
    { const char * tb_v7533 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7533; }
    { const char * tb_v7534 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v7534; }
    { const char * tb_v7535 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7535; }
    { const char * tb_v7536 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7536; }
    { const char * tb_v7537 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7537; }
    { const char * tb_v7538 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v7538; }
    { const char * tb_v7539 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v7539; }
    { const char * tb_v7540 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7540; }
    { const char * tb_v7541 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7541; }
    { const char * tb_v7542 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7542; }
    { const char * tb_v7543 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7543; }
    { const char * tb_v7544 = "        code |= (int)tb_zbits(z, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7544; }
    { const char * tb_v7545 = "        int c = h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v7545; }
