    { const char * tb_v7562 = "        int type = (int)tb_zbits(z, 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v7562; }
    { const char * tb_v7563 = "        if (type == 0) {   // без сжатия\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "            z->bits >>= z->nb & 7; z->nb -= z->nb & 7;\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "            unsigned len = tb_zbits(z, 16), nlen = tb_zbits(z, 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "            if ((len ^ 0xFFFF) != nlen) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "            while (len-- && !z->err) tb_zput(z, (unsigned char)tb_zbits(z, 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "        } else if (type == 1 || type == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "            tb_huff lh, dh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
