    { const char * tb_v8227 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
