    { const char * tb_v8244 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8244; }
    { const char * tb_v8245 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8245; }
    { const char * tb_v8246 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8246; }
    { const char * tb_v8247 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v8247; }
    { const char * tb_v8248 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v8248; }
    { const char * tb_v8249 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8249; }
    { const char * tb_v8250 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8250; }
    { const char * tb_v8251 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8251; }
    { const char * tb_v8252 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8252; }
    { const char * tb_v8253 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8253; }
    { const char * tb_v8254 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8254; }
    { const char * tb_v8255 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8255; }
    { const char * tb_v8256 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8256; }
    { const char * tb_v8257 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8257; }
    { const char * tb_v8258 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8258; }
    { const char * tb_v8259 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8259; }
    { const char * tb_v8260 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8260; }
    { const char * tb_v8261 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8261; }
    { const char * tb_v8262 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8262; }
    { const char * tb_v8263 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v8263; }
    { const char * tb_v8264 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8264; }
    { const char * tb_v8265 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8265; }
    { const char * tb_v8266 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8266; }
