    { const char * tb_v8792 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8792; }
    { const char * tb_v8793 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8793; }
