    { const char * tb_v8850 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v8850; }
    { const char * tb_v8851 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8851; }
    { const char * tb_v8852 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8852; }
    { const char * tb_v8853 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8853; }
    { const char * tb_v8854 = "// 3 — «новый» треугольник, 4 — он же прозрачный (глубину не пишет)\n"; *(const char * *)tb_grow(v_lines) = tb_v8854; }
    { const char * tb_v8855 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 28) & 1u ? 3 + (int)((m >> 27) & 1u) : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8855; }
    { const char * tb_v8856 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8856; }
    { const char * tb_v8857 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8857; }
    { const char * tb_v8858 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v8858; }
