    { const char * tb_v11838 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11838; }
    { const char * tb_v11839 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v11839; }
    { const char * tb_v11840 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v11840; }
    { const char * tb_v11841 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v11841; }
