    { const char * tb_v11848 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11848; }
    { const char * tb_v11849 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11849; }
    { const char * tb_v11850 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11850; }
    { const char * tb_v11851 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11851; }
    { const char * tb_v11852 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11852; }
