    { const char * tb_v13546 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v13546; }
    { const char * tb_v13547 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v13547; }
    { const char * tb_v13548 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v13548; }
    { const char * tb_v13549 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v13549; }
    { const char * tb_v13550 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v13550; }
    { const char * tb_v13551 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13551; }
    { const char * tb_v13552 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13552; }
    { const char * tb_v13553 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13553; }
    { const char * tb_v13554 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13554; }
    { const char * tb_v13555 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13555; }
    { const char * tb_v13556 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v13556; }
    { const char * tb_v13557 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13557; }
    { const char * tb_v13558 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v13558; }
    { const char * tb_v13559 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v13559; }
    { const char * tb_v13560 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v13560; }
    { const char * tb_v13561 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13561; }
    { const char * tb_v13562 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13562; }
    { const char * tb_v13563 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v13563; }
    { const char * tb_v13564 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v13564; }
    { const char * tb_v13565 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v13565; }
    { const char * tb_v13566 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13566; }
    { const char * tb_v13567 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13567; }
    { const char * tb_v13568 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13568; }
    { const char * tb_v13569 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13569; }
    { const char * tb_v13570 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13570; }
    { const char * tb_v13571 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13571; }
    { const char * tb_v13572 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13572; }
    { const char * tb_v13573 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13573; }
    { const char * tb_v13574 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13574; }
    { const char * tb_v13575 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13575; }
    { const char * tb_v13576 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13576; }
    { const char * tb_v13577 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13577; }
