    { const char * tb_v13606 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v13606; }
    { const char * tb_v13607 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v13607; }
    { const char * tb_v13608 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v13608; }
    { const char * tb_v13609 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13609; }
    { const char * tb_v13610 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13610; }
