    { const char * tb_v13757 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13757; }
    { const char * tb_v13758 = "    if (tb_px || tb_wn) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13758; }
    { const char * tb_v13759 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13759; }
    { const char * tb_v13760 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13760; }
