    { const char * tb_v13771 = "    tb_wn = 1; tb_wcur = 0; tb_wins[0].used = 1; tb_whand[0] = tb_gfx_handle();\n"; *(const char * *)tb_grow(v_lines) = tb_v13771; }
    { const char * tb_v13772 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13772; }
