    { const char * tb_v13788 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, tb_tr(\"видеокарта: не получилось поменять размер кадра\\n\"));\n"; *(const char * *)tb_grow(v_lines) = tb_v13788; }
    { const char * tb_v13789 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13789; }
    { const char * tb_v13790 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13790; }
    { const char * tb_v13791 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13791; }
    { const char * tb_v13792 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v13792; }
