    { const char * tb_v13794 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13794; }
    { const char * tb_v13795 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13795; }
    { const char * tb_v13796 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13796; }
    { const char * tb_v13797 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13797; }
    { const char * tb_v13798 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13798; }
    { const char * tb_v13799 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13799; }
    { const char * tb_v13800 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13800; }
    { const char * tb_v13801 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13801; }
    { const char * tb_v13802 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13802; }
    { const char * tb_v13803 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v13803; }
    { const char * tb_v13804 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13804; }
    { const char * tb_v13805 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v13805; }
    { const char * tb_v13806 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13806; }
    { const char * tb_v13807 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13807; }
    { const char * tb_v13808 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13808; }
    { const char * tb_v13809 = "    if (tb_wn > 1) tb_windows_after();\n"; *(const char * *)tb_grow(v_lines) = tb_v13809; }
    { const char * tb_v13810 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
    { const char * tb_v13814 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13814; }
    { const char * tb_v13815 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13815; }
    { const char * tb_v13816 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13816; }
    { const char * tb_v13817 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13817; }
    { const char * tb_v13818 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v13818; }
    { const char * tb_v13819 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v13819; }
    { const char * tb_v13820 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v13820; }
    { const char * tb_v13821 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v13821; }
    { const char * tb_v13822 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13822; }
    { const char * tb_v13823 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13823; }
    { const char * tb_v13824 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13824; }
    { const char * tb_v13825 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13825; }
    { const char * tb_v13826 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13826; }
    { const char * tb_v13827 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13827; }
    { const char * tb_v13828 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v13828; }
    { const char * tb_v13829 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v13829; }
    { const char * tb_v13830 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13830; }
    { const char * tb_v13831 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13831; }
    { const char * tb_v13832 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13832; }
    { const char * tb_v13833 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13833; }
    { const char * tb_v13834 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v13834; }
    { const char * tb_v13835 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v13835; }
    { const char * tb_v13836 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v13836; }
    { const char * tb_v13837 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v13837; }
    { const char * tb_v13838 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13838; }
    { const char * tb_v13839 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13839; }
    { const char * tb_v13840 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13840; }
    { const char * tb_v13841 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13841; }
    { const char * tb_v13842 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v13842; }
    { const char * tb_v13843 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13843; }
    { const char * tb_v13844 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13844; }
    { const char * tb_v13845 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13845; }
    { const char * tb_v13846 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13846; }
    { const char * tb_v13847 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13847; }
    { const char * tb_v13848 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13848; }
    { const char * tb_v13849 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13849; }
    { const char * tb_v13850 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13850; }
    { const char * tb_v13851 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v13851; }
    { const char * tb_v13852 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13852; }
