    { const char * tb_v13892 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v13892; }
    { const char * tb_v13893 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13893; }
    { const char * tb_v13894 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13894; }
    { const char * tb_v13895 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13895; }
    { const char * tb_v13896 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13896; }
    { const char * tb_v13897 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13897; }
