    { const char * tb_v13905 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13905; }
    { const char * tb_v13906 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13906; }
