    { const char * tb_v13913 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v13913; }
    { const char * tb_v13914 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13914; }
    { const char * tb_v13915 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v13915; }
    { const char * tb_v13916 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13916; }
    { const char * tb_v13917 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v13917; }
    { const char * tb_v13918 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v13918; }
    { const char * tb_v13919 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13919; }
    { const char * tb_v13920 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13920; }
