    { const char * tb_v13924 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13924; }
    { const char * tb_v13925 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v13925; }
    { const char * tb_v13926 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13926; }
    { const char * tb_v13927 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v13927; }
    { const char * tb_v13928 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13928; }
    { const char * tb_v13929 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v13929; }
    { const char * tb_v13930 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13930; }
    { const char * tb_v13931 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13931; }
    { const char * tb_v13932 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13932; }
    { const char * tb_v13933 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v13933; }
    { const char * tb_v13934 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13934; }
    { const char * tb_v13935 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13935; }
    { const char * tb_v13936 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13936; }
    { const char * tb_v13937 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v13937; }
    { const char * tb_v13938 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13938; }
    { const char * tb_v13939 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13939; }
    { const char * tb_v13940 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13940; }
    { const char * tb_v13941 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13941; }
    { const char * tb_v13942 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13942; }
    { const char * tb_v13943 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13943; }
    { const char * tb_v13944 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13944; }
    { const char * tb_v13945 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13945; }
    { const char * tb_v13946 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v13946; }
    { const char * tb_v13947 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13947; }
    { const char * tb_v13948 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v13948; }
    { const char * tb_v13949 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v13949; }
    { const char * tb_v13950 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v13950; }
    { const char * tb_v13951 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13951; }
    { const char * tb_v13952 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13952; }
    { const char * tb_v13953 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v13953; }
    { const char * tb_v13954 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13954; }
    { const char * tb_v13955 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13955; }
    { const char * tb_v13956 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v13956; }
    { const char * tb_v13957 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13957; }
