    { const char * tb_v13961 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13961; }
    { const char * tb_v13962 = "                double dx = i + 0.5 - (cx + 0.5), dy = j + 0.5 - (cy + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13962; }
    { const char * tb_v13963 = "                double d = sqrt(dx * dx + dy * dy);\n"; *(const char * *)tb_grow(v_lines) = tb_v13963; }
    { const char * tb_v13964 = "                tb_cover(i, j, cc, r - d + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13964; }
    { const char * tb_v13965 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v13965; }
    { const char * tb_v13966 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13966; }
    { const char * tb_v13967 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13967; }
    { const char * tb_v13968 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13968; }
    { const char * tb_v13969 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v13969; }
    { const char * tb_v13970 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v13970; }
    { const char * tb_v13971 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13971; }
    { const char * tb_v13972 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v13972; }
    { const char * tb_v13973 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13973; }
    { const char * tb_v13974 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v13974; }
    { const char * tb_v13975 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13975; }
    { const char * tb_v13976 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v13976; }
    { const char * tb_v13977 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13977; }
    { const char * tb_v13978 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13978; }
    { const char * tb_v13979 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13979; }
    { const char * tb_v13980 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v13980; }
    { const char * tb_v13981 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v13981; }
    { const char * tb_v13982 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v13982; }
    { const char * tb_v13983 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13983; }
    { const char * tb_v13984 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13984; }
    { const char * tb_v13985 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13985; }
    { const char * tb_v13986 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13986; }
