    { const char * tb_v13988 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v13988; }
    { const char * tb_v13989 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v13989; }
    { const char * tb_v13990 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13990; }
    { const char * tb_v13991 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13991; }
    { const char * tb_v13992 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13992; }
    { const char * tb_v13993 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13993; }
    { const char * tb_v13994 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13994; }
    { const char * tb_v13995 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13995; }
    { const char * tb_v13996 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v13996; }
    { const char * tb_v13997 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13997; }
    { const char * tb_v13998 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13998; }
    { const char * tb_v13999 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13999; }
    { const char * tb_v14000 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14000; }
    { const char * tb_v14001 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
    { const char * tb_v14010 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14010; }
    { const char * tb_v14011 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14011; }
    { const char * tb_v14012 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14012; }
    { const char * tb_v14013 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v14013; }
    { const char * tb_v14014 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v14014; }
    { const char * tb_v14015 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14015; }
    { const char * tb_v14016 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14016; }
    { const char * tb_v14017 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
    { const char * tb_v14020 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14020; }
    { const char * tb_v14021 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14021; }
    { const char * tb_v14022 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14022; }
    { const char * tb_v14023 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
    { const char * tb_v14026 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14026; }
    { const char * tb_v14027 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14027; }
    { const char * tb_v14028 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v14028; }
    { const char * tb_v14029 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v14029; }
    { const char * tb_v14030 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14030; }
    { const char * tb_v14031 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14031; }
    { const char * tb_v14032 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14032; }
    { const char * tb_v14033 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14033; }
    { const char * tb_v14034 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14034; }
    { const char * tb_v14035 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14035; }
    { const char * tb_v14036 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14036; }
    { const char * tb_v14037 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14037; }
    { const char * tb_v14038 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14038; }
    { const char * tb_v14039 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14039; }
    { const char * tb_v14040 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14040; }
    { const char * tb_v14041 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14041; }
    { const char * tb_v14042 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14042; }
    { const char * tb_v14043 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14043; }
    { const char * tb_v14044 = "            if (i * i + j * j <= r * r + r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14044; }
    { const char * tb_v14045 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "                else tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
    { const char * tb_v14047 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14047; }
    { const char * tb_v14048 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14048; }
    { const char * tb_v14049 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14049; }
    { const char * tb_v14050 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14050; }
    { const char * tb_v14051 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14051; }
    { const char * tb_v14052 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14052; }
    { const char * tb_v14053 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14053; }
    { const char * tb_v14054 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14054; }
    { const char * tb_v14055 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v14055; }
    { const char * tb_v14056 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14056; }
    { const char * tb_v14057 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v14057; }
    { const char * tb_v14058 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14058; }
    { const char * tb_v14059 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v14059; }
    { const char * tb_v14060 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14060; }
    { const char * tb_v14061 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14061; }
    { const char * tb_v14062 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14062; }
    { const char * tb_v14063 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14063; }
    { const char * tb_v14064 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14064; }
    { const char * tb_v14065 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v14065; }
    { const char * tb_v14066 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14066; }
    { const char * tb_v14067 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14067; }
    { const char * tb_v14068 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v14068; }
    { const char * tb_v14069 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v14069; }
    { const char * tb_v14070 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v14070; }
    { const char * tb_v14071 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v14071; }
    { const char * tb_v14072 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14072; }
    { const char * tb_v14073 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v14073; }
    { const char * tb_v14074 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14074; }
    { const char * tb_v14075 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14075; }
    { const char * tb_v14076 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14076; }
    { const char * tb_v14077 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14077; }
    { const char * tb_v14078 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14078; }
    { const char * tb_v14079 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14079; }
    { const char * tb_v14080 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14080; }
    { const char * tb_v14081 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14081; }
    { const char * tb_v14082 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14082; }
    { const char * tb_v14083 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14083; }
    { const char * tb_v14084 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14084; }
    { const char * tb_v14085 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14085; }
    { const char * tb_v14086 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14086; }
    { const char * tb_v14087 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14087; }
    { const char * tb_v14088 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14088; }
    { const char * tb_v14089 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v14089; }
    { const char * tb_v14090 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v14090; }
    { const char * tb_v14091 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14091; }
    { const char * tb_v14092 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v14092; }
    { const char * tb_v14093 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v14093; }
    { const char * tb_v14094 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14094; }
    { const char * tb_v14095 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14095; }
    { const char * tb_v14096 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14096; }
    { const char * tb_v14097 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14097; }
    { const char * tb_v14098 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14098; }
    { const char * tb_v14099 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14099; }
    { const char * tb_v14100 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v14100; }
    { const char * tb_v14101 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v14101; }
    { const char * tb_v14102 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v14102; }
    { const char * tb_v14103 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14103; }
    { const char * tb_v14104 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14104; }
    { const char * tb_v14105 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14105; }
    { const char * tb_v14106 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14106; }
    { const char * tb_v14107 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14107; }
    { const char * tb_v14108 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14108; }
    { const char * tb_v14109 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14109; }
    { const char * tb_v14110 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v14110; }
