    { const char * tb_v14315 = "    tb_meshes[i].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14315; }
    { const char * tb_v14316 = "    tb_meshes[i].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14316; }
    { const char * tb_v14317 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14317; }
    { const char * tb_v14318 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14318; }
    { const char * tb_v14319 = "    if (tb_nmfree > 0) { long long i = tb_mfree[--tb_nmfree]; tb_mesh_reset(i); return i; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14319; }
    { const char * tb_v14320 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14320; }
    { const char * tb_v14321 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14321; }
    { const char * tb_v14322 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14322; }
    { const char * tb_v14323 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14323; }
    { const char * tb_v14324 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14324; }
    { const char * tb_v14325 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14325; }
    { const char * tb_v14326 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14326; }
    { const char * tb_v14327 = "    tb_meshes[tb_nmesh].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14327; }
    { const char * tb_v14328 = "    tb_meshes[tb_nmesh].shp = tb_meshes[tb_nmesh].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14328; }
    { const char * tb_v14329 = "    tb_meshes[tb_nmesh].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14329; }
    { const char * tb_v14330 = "    tb_meshes[tb_nmesh].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14330; }
    { const char * tb_v14331 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14331; }
    { const char * tb_v14332 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14332; }
    { const char * tb_v14333 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14333; }
    { const char * tb_v14334 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14334; }
    { const char * tb_v14335 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14335; }
    { const char * tb_v14336 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14336; }
    { const char * tb_v14337 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14337; }
    { const char * tb_v14338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14338; }
    { const char * tb_v14339 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v14339; }
    { const char * tb_v14340 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14340; }
    { const char * tb_v14341 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v14341; }
    { const char * tb_v14342 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14342; }
    { const char * tb_v14343 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v14343; }
    { const char * tb_v14344 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14344; }
    { const char * tb_v14345 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14345; }
    { const char * tb_v14346 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14346; }
    { const char * tb_v14347 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14347; }
    { const char * tb_v14348 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14348; }
    { const char * tb_v14349 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14349; }
    { const char * tb_v14350 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14350; }
    { const char * tb_v14351 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v14351; }
    { const char * tb_v14352 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14352; }
    { const char * tb_v14353 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14353; }
    { const char * tb_v14354 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14354; }
    { const char * tb_v14355 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v14355; }
    { const char * tb_v14356 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14356; }
    { const char * tb_v14357 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14357; }
    { const char * tb_v14358 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14358; }
    { const char * tb_v14359 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14359; }
    { const char * tb_v14360 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14360; }
    { const char * tb_v14361 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14361; }
    { const char * tb_v14362 = "        if (m->sb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14362; }
    { const char * tb_v14363 = "            m->sb = (int16_t *)realloc(m->sb, sizeof(int16_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14363; }
    { const char * tb_v14364 = "            m->sw = (float *)realloc(m->sw, sizeof(float) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14364; }
    { const char * tb_v14365 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14365; }
    { const char * tb_v14366 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14366; }
    { const char * tb_v14367 = "    if (m->sb) for (int i = 0; i < 4; i++) { m->sb[4 * m->nv + i] = -1; m->sw[4 * m->nv + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14367; }
    { const char * tb_v14368 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14368; }
    { const char * tb_v14369 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14369; }
    { const char * tb_v14370 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14370; }
    { const char * tb_v14371 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14371; }
    { const char * tb_v14372 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v14372; }
    { const char * tb_v14373 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v14373; }
