    { const char * tb_v14922 = "static void tb_draw_mesh_r(long long id, double x, double y, double z, double R[3][3]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14922; }
    { const char * tb_v14923 = "    if (!tb_px || id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14923; }
