    { const char * tb_v14931 = "    tb_zclr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14931; }
    { const char * tb_v14932 = "    // даль: mesh_far — дальше не рисовать, mesh_lod — дальше рисовать другую (попроще) сетку\n"; *(const char * *)tb_grow(v_lines) = tb_v14932; }
    { const char * tb_v14933 = "    for (int hop = 0; hop < 8; hop++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14933; }
    { const char * tb_v14934 = "        tb_mesh *q = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v14934; }
    { const char * tb_v14935 = "        if (q->far <= 0 && q->lod < 0) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v14935; }
