    { const char * tb_v14937 = "        tb_mesh_center(q, x, y, z, R, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14937; }
    { const char * tb_v14938 = "        double dd = sqrt((c[0] - tb_cam[0]) * (c[0] - tb_cam[0]) + (c[1] - tb_cam[1]) * (c[1] - tb_cam[1]) + (c[2] - tb_cam[2]) * (c[2] - tb_cam[2]));\n"; *(const char * *)tb_grow(v_lines) = tb_v14938; }
    { const char * tb_v14939 = "        if (q->far > 0 && dd > q->far) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14939; }
    { const char * tb_v14940 = "        if (q->lod >= 0 && q->lod < tb_nmesh && q->lod != id && dd > q->lodd) { id = q->lod; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14940; }
    { const char * tb_v14941 = "        break;\n"; *(const char * *)tb_grow(v_lines) = tb_v14941; }
    { const char * tb_v14942 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14942; }
    { const char * tb_v14943 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v14943; }
    { const char * tb_v14944 = "    if (m->n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14944; }
    { const char * tb_v14945 = "    // поворот сетки и взгляд камеры — одна таблица M (3 × 3) и сдвиг T: угол p перед камерой = M p + T\n"; *(const char * *)tb_grow(v_lines) = tb_v14945; }
    { const char * tb_v14946 = "    double M[3][3], T[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14946; }
    { const char * tb_v14947 = "    double d[3] = { x - tb_cam[0], y - tb_cam[1], z - tb_cam[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v14947; }
    { const char * tb_v14948 = "    for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14948; }
    { const char * tb_v14949 = "        const double *row = k == 0 ? tb_cam + 3 : k == 1 ? tb_cam + 6 : tb_camf;\n"; *(const char * *)tb_grow(v_lines) = tb_v14949; }
    { const char * tb_v14950 = "        for (int j = 0; j < 3; j++) M[k][j] = row[0] * R[0][j] + row[1] * R[1][j] + row[2] * R[2][j];\n"; *(const char * *)tb_grow(v_lines) = tb_v14950; }
    { const char * tb_v14951 = "        T[k] = row[0] * d[0] + row[1] * d[1] + row[2] * d[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14951; }
    { const char * tb_v14952 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14952; }
    { const char * tb_v14953 = "    if (m->shp >= 0 || m->shc >= 0) { tb_sh_submit(id, x, y, z, R); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14953; }
    { const char * tb_v14954 = "    tb_mesh_chunks(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v14954; }
