    { const char * tb_v16511 = "    // раскладка xpad (Xbox и большинство совместимых): кнопки 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 back, 7 start, 8 home, 9 L3, 10 R3;\n"; *(const char * *)tb_grow(v_lines) = tb_v16511; }
    { const char * tb_v16512 = "    // оси 0 lx, 1 ly, 2 lt, 3 rx, 4 ry, 5 rt, 6 крестовина x, 7 крестовина y\n"; *(const char * *)tb_grow(v_lines) = tb_v16512; }
    { const char * tb_v16513 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16513; }
    { const char * tb_v16514 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16514; }
