    { const char * tb_v16518 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v16518; }
    { const char * tb_v16519 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v16519; }
