    { const char * tb_v16522 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16522; }
    { const char * tb_v16523 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16523; }
    { const char * tb_v16524 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16524; }
    { const char * tb_v16525 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16525; }
