    { const char * tb_v16529 = "                case 2: p->a[TB_PA_L2] = (v + 1) / 2; p->b[TB_PB_L2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16529; }
    { const char * tb_v16530 = "                case 3: p->a[TB_PA_RX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16530; }
    { const char * tb_v16531 = "                case 4: p->a[TB_PA_RY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16531; }
