    { const char * tb_v16533 = "                case 6: p->b[TB_PB_LEFT] = e.value < -8000; p->b[TB_PB_RIGHT] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16533; }
    { const char * tb_v16534 = "                case 7: p->b[TB_PB_UP] = e.value < -8000; p->b[TB_PB_DOWN] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v16534; }
    { const char * tb_v16535 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v16535; }
