    { const char * tb_v16583 = "    char *got = tb_gfx_clip_get();   // malloc или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v16583; }
    { const char * tb_v16584 = "    size_t n = got ? strlen(got) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16584; }
