    { const char * tb_v16592 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v16592; }
    { const char * tb_v16593 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16593; }
    { const char * tb_v16594 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v16594; }
