    { const char * tb_v16596 = "        if (strcmp(name, names[i]) == 0) { tb_cursor_prog = i; if (tb_px) { if (!tb_mlock) tb_gfx_cursor(i); } else tb_cursor_want = i; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16596; }
