    { const char * tb_v16601 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v16601; }
    { const char * tb_v16602 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v16602; }
    { const char * tb_v16603 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v16603; }
    { const char * tb_v16604 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v16604; }
    { const char * tb_v16605 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v16605; }
    { const char * tb_v16606 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v16606; }
    { const char * tb_v16607 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v16607; }
    { const char * tb_v16608 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v16608; }
    { const char * tb_v16609 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v16609; }
    { const char * tb_v16610 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v16610; }
    { const char * tb_v16611 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v16611; }
    { const char * tb_v16612 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v16612; }
    { const char * tb_v16613 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v16613; }
    { const char * tb_v16614 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v16614; }
    { const char * tb_v16615 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v16615; }
    { const char * tb_v16616 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v16616; }
    { const char * tb_v16617 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v16617; }
    { const char * tb_v16618 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v16618; }
    { const char * tb_v16619 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v16619; }
    { const char * tb_v16620 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v16620; }
    { const char * tb_v16621 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v16621; }
    { const char * tb_v16622 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v16622; }
    { const char * tb_v16623 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16623; }
    { const char * tb_v16624 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v16624; }
    { const char * tb_v16625 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v16625; }
    { const char * tb_v16626 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v16626; }
    { const char * tb_v16627 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16627; }
    { const char * tb_v16628 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v16628; }
    { const char * tb_v16629 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v16629; }
    { const char * tb_v16630 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v16630; }
    { const char * tb_v16631 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v16631; }
    { const char * tb_v16632 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v16632; }
    { const char * tb_v16633 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v16633; }
    { const char * tb_v16634 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v16634; }
    { const char * tb_v16635 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16635; }
    { const char * tb_v16636 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16636; }
    { const char * tb_v16637 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16637; }
    { const char * tb_v16638 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v16638; }
    { const char * tb_v16639 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v16639; }
    { const char * tb_v16640 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16640; }
    { const char * tb_v16641 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16641; }
    { const char * tb_v16642 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16642; }
    { const char * tb_v16643 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16643; }
    { const char * tb_v16644 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16644; }
    { const char * tb_v16645 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16645; }
    { const char * tb_v16646 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v16646; }
    { const char * tb_v16647 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16647; }
    { const char * tb_v16648 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v16648; }
    { const char * tb_v16649 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16649; }
    { const char * tb_v16650 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v16650; }
    { const char * tb_v16651 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16651; }
    { const char * tb_v16652 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v16652; }
    { const char * tb_v16653 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16653; }
    { const char * tb_v16654 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v16654; }
    { const char * tb_v16655 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v16655; }
    { const char * tb_v16656 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16656; }
    { const char * tb_v16657 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16657; }
    { const char * tb_v16658 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v16658; }
    { const char * tb_v16659 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16659; }
    { const char * tb_v16660 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16660; }
    { const char * tb_v16661 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v16661; }
    { const char * tb_v16662 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16662; }
    { const char * tb_v16663 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16663; }
    { const char * tb_v16664 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16664; }
    { const char * tb_v16665 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16665; }
    { const char * tb_v16666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16666; }
    { const char * tb_v16667 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v16667; }
    { const char * tb_v16668 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16668; }
    { const char * tb_v16669 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16669; }
    { const char * tb_v16670 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v16670; }
    { const char * tb_v16671 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16671; }
    { const char * tb_v16672 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16672; }
    { const char * tb_v16673 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16673; }
    { const char * tb_v16674 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16674; }
    { const char * tb_v16675 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16675; }
    { const char * tb_v16676 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v16676; }
    { const char * tb_v16677 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v16677; }
    { const char * tb_v16678 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v16678; }
    { const char * tb_v16679 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16679; }
    { const char * tb_v16680 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16680; }
    { const char * tb_v16681 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v16681; }
    { const char * tb_v16682 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16682; }
    { const char * tb_v16683 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16683; }
    { const char * tb_v16684 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16684; }
    { const char * tb_v16685 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16685; }
    { const char * tb_v16686 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v16686; }
    { const char * tb_v16687 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v16687; }
    { const char * tb_v16688 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16688; }
    { const char * tb_v16689 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16689; }
    { const char * tb_v16690 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v16690; }
    { const char * tb_v16691 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16691; }
    { const char * tb_v16692 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16692; }
    { const char * tb_v16693 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v16693; }
    { const char * tb_v16694 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v16694; }
    { const char * tb_v16695 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v16695; }
    { const char * tb_v16696 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16696; }
    { const char * tb_v16697 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16697; }
    { const char * tb_v16698 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16698; }
    { const char * tb_v16699 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16699; }
    { const char * tb_v16700 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16700; }
    { const char * tb_v16701 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v16701; }
    { const char * tb_v16702 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16702; }
    { const char * tb_v16703 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v16703; }
    { const char * tb_v16704 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v16704; }
    { const char * tb_v16705 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16705; }
    { const char * tb_v16706 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16706; }
    { const char * tb_v16707 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16707; }
    { const char * tb_v16708 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16708; }
    { const char * tb_v16709 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16709; }
    { const char * tb_v16710 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16710; }
    { const char * tb_v16711 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16711; }
