    { const char * tb_v16943 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v16943; }
    { const char * tb_v16944 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16944; }
    { const char * tb_v16945 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16945; }
    { const char * tb_v16946 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16946; }
    { const char * tb_v16947 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v16947; }
