    { const char * tb_v17648 = "    end_all = max([secs[k][\"addr\"] + secs[k][\"size\"] for k in order] + [extra[\"tb_heap_area\"]])\n"; *(const char * *)tb_grow(v_lines) = tb_v17648; }
